ST.xhtml:
(* Dupla confirmação *)
xIsExtended  := xSensExtended AND NOT xSensRetracted;
xIsRetracted := xSensRetracted AND NOT xSensExtended;

IF xReset THEN
    xFault := FALSE;
    iFaultCode := 0;
END_IF

(* Supervisão de tempo e de coerência dos sensores *)
tonExt(IN := xEnable AND xValve AND NOT xIsExtended AND NOT xFault, PT := tMoveTimeout);
tonRet(IN := xEnable AND NOT xValve AND NOT xIsRetracted AND NOT xFault, PT := tMoveTimeout);
tonBoth(IN := xEnable AND xSensExtended AND xSensRetracted, PT := tSensorConflict);

IF NOT xFault THEN
    IF tonExt.Q THEN
        xFault := TRUE; iFaultCode := 1;
    ELSIF tonRet.Q THEN
        xFault := TRUE; iFaultCode := 2;
    ELSIF tonBoth.Q THEN
        xFault := TRUE; iFaultCode := 3;
    END_IF
END_IF

(* Saída da válvula: em falha ou sem habilitação, retorna por mola *)
xValve := xEnable AND xCmdExtend AND NOT xFault;

xVacValve := xEnable AND xGrip;

(* Janela de sopro após o comando de liberação *)
ftGrip(CLK := xGrip);
IF ftGrip.Q THEN
    xBlow := TRUE;
END_IF
tonBlow(IN := xBlow, PT := tBlow);
IF tonBlow.Q OR xGrip OR NOT xEnable THEN
    xBlow := FALSE;
END_IF
xBlowValve := xBlow AND xEnable;

(* Confirmação da pega *)
tonOk(IN := xGrip AND xPressostat, PT := tDebounce);
xGripOk := tonOk.Q;

(* Falha de pega: vácuo não estabelecido no tempo *)
tonConfirm(IN := xEnable AND xGrip AND NOT xGripOk, PT := tConfirm);
IF tonConfirm.Q THEN
    xPickFail := TRUE;
END_IF
IF xReset OR NOT xGrip THEN
    xPickFail := FALSE;
END_IF

(* Perda de vácuo durante o transporte *)
IF xGripOk THEN
    xCarried := TRUE;
END_IF
IF NOT xGrip THEN
    xCarried := FALSE;
END_IF
tonLoss(IN := xCarried AND xGrip AND NOT xPressostat, PT := tDebounce);
xGripLoss := tonLoss.Q;

(* Confirmação da liberação *)
tonRel(IN := NOT xGrip AND NOT xPressostat, PT := tDebounce);
xReleased := tonRel.Q;

xDriveExecute := FALSE;
rtHome(CLK := xHomeCmd);
rtMove(CLK := xMoveCmd);

tonReady(IN := (iState = AS_WAIT_READY), PT := tReadyTimeout);
tonHome(IN := (iState = AS_HOMING), PT := tHomeTimeout);
tonMove(IN := (iState = AS_MOVING), PT := tMoveTimeout);
tonSettle(IN := (iState = AS_MOVING) AND (ABS(rActPos - rLastSetpoint) <= rInPosWindow),
          PT := tSettle);

(* Supervisão geral *)
IF iState <> AS_FAULT THEN
    IF NOT xEnable THEN
        iState := AS_OFF;
    ELSIF iState >= AS_WAIT_READY THEN
        IF xDriveFault THEN
            iFaultCode := 5; iState := AS_FAULT;
        ELSIF (iState >= AS_UNHOMED) AND NOT xDriveReady THEN
            iFaultCode := 6; iState := AS_FAULT;
        END_IF
    END_IF
END_IF

CASE iState OF
    AS_OFF:
        xHomed := FALSE;
        IF xEnable THEN
            iState := AS_WAIT_READY;
        END_IF

    AS_WAIT_READY:
        IF xDriveReady THEN
            iState := AS_UNHOMED;
        ELSIF tonReady.Q THEN
            iFaultCode := 1; iState := AS_FAULT;
        END_IF

    AS_UNHOMED:
        IF rtHome.Q THEN
            iState := AS_HOMING;
        END_IF

    AS_HOMING:
        IF xDriveHomeDone THEN
            xHomed := TRUE;
            rLastSetpoint := rActPos;
            iState := AS_READY;
        ELSIF tonHome.Q THEN
            iFaultCode := 2; iState := AS_FAULT;
        END_IF

    AS_READY:
        IF rtHome.Q THEN
            xHomed := FALSE;
            iState := AS_HOMING;
        ELSIF rtMove.Q THEN
            IF (rTarget < rSoftMin) OR (rTarget > rSoftMax) THEN
                iFaultCode := 3; iState := AS_FAULT;
            ELSE
                rLatchTarget := rTarget;
                iState := AS_START;
            END_IF
        END_IF

    AS_START:
        rDriveSetpoint := rLatchTarget;
        rLastSetpoint := rLatchTarget;
        xDriveExecute := TRUE;
        iState := AS_MOVING;

    AS_MOVING:
        IF xHalt AND NOT xHaltDone THEN
            (* Parada: novo alvo = posição atual *)
            rDriveSetpoint := rActPos;
            rLastSetpoint := rActPos;
            xDriveExecute := TRUE;
            xHaltDone := TRUE;
        END_IF
        IF tonSettle.Q THEN
            iState := AS_READY;
        ELSIF tonMove.Q THEN
            iFaultCode := 4; iState := AS_FAULT;
        END_IF

    AS_FAULT:
        xHomed := FALSE;
        IF xReset AND NOT xDriveFault THEN
            iFaultCode := 0;
            iState := AS_OFF;
        END_IF
END_CASE

IF iState <> AS_MOVING THEN
    xHaltDone := FALSE;
END_IF

(* Saídas *)
xDrivePower := (iState >= AS_WAIT_READY) AND (iState <> AS_FAULT);
xDriveHome  := (iState = AS_HOMING);
xBusy       := (iState = AS_HOMING) OR (iState = AS_START) OR (iState = AS_MOVING);
xAccept     := (iState = AS_UNHOMED) OR (iState = AS_READY);
xInPos      := (iState = AS_READY) AND xHomed AND (ABS(rActPos - rLastSetpoint) <= rInPosWindow);
xFault      := (iState = AS_FAULT);

(* Filtros dos sensores *)
tonP1(IN := xSensZ1, PT := tSensorFilter);   xP1 := tonP1.Q;
tonP2(IN := xSensZ2, PT := tSensorFilter);   xP2 := tonP2.Q;
tonP3(IN := xSensZ3, PT := tSensorFilter);   xP3 := tonP3.Q;
tonA1(IN := NOT xSensZ1, PT := tClearDelay); xA1 := tonA1.Q;
tonA2(IN := NOT xSensZ2, PT := tClearDelay); xA2 := tonA2.Q;
tonA3(IN := NOT xSensZ3, PT := tClearDelay); xA3 := tonA3.Q;

IF xReset THEN
    xFault := FALSE;
END_IF

(* Ressincronização: considera placa posicionada onde houver sensor ativo *)
IF xClearZones THEN
    IF xSensZ1 THEN iZ1 := ZS_OCC; ELSE iZ1 := ZS_EMPTY; END_IF
    IF xSensZ2 THEN iZ2 := ZS_OCC; ELSE iZ2 := ZS_EMPTY; END_IF
    IF xSensZ3 THEN iZ3 := ZS_OCC; ELSE iZ3 := ZS_EMPTY; END_IF
    xFault := FALSE;
END_IF

(* Timeout de transferência (motores acionados no ciclo anterior) *)
tonT1(IN := xMotor1, PT := tTransferTimeout);
tonT2(IN := xMotor2, PT := tTransferTimeout);
tonT3(IN := xMotor3, PT := tTransferTimeout);
IF tonT1.Q OR tonT2.Q OR tonT3.Q THEN
    xFault := TRUE;
END_IF

xActive := xEnable AND NOT xFault;

(* ---------- Zona 1: entrada ---------- *)
CASE iZ1 OF
    ZS_EMPTY:
        IF xActive AND xUpBoardAvail THEN
            iZ1 := ZS_RECV;
        END_IF
    ZS_RECV:
        IF xP1 THEN
            iZ1 := ZS_OCC;
        END_IF
    ZS_OCC:
        IF xActive AND (iZ2 = ZS_EMPTY) THEN
            iZ1 := ZS_SEND;
            iZ2 := ZS_RECV;     (* Transferência 1 -> 2 *)
        END_IF
    ZS_SEND:
        IF (iZ2 = ZS_OCC) AND xA1 THEN
            iZ1 := ZS_EMPTY;
        END_IF
END_CASE

(* ---------- Zona 2: montagem ---------- *)
CASE iZ2 OF
    ZS_EMPTY:
        ;
    ZS_RECV:
        IF xP2 THEN
            iZ2 := ZS_OCC;
        END_IF
    ZS_OCC:
        IF xActive AND xAsmDone AND (iZ3 = ZS_EMPTY) THEN
            iZ2 := ZS_SEND;
            iZ3 := ZS_RECV;     (* Transferência 2 -> 3 *)
        END_IF
    ZS_SEND:
        IF (iZ3 = ZS_OCC) AND xA2 THEN
            iZ2 := ZS_EMPTY;
        END_IF
END_CASE

(* ---------- Zona 3: saída / inspeção ---------- *)
CASE iZ3 OF
    ZS_EMPTY:
        ;
    ZS_RECV:
        IF xP3 THEN
            iZ3 := ZS_OCC;
        END_IF
    ZS_OCC:
        IF xActive AND xInspDone THEN
            iZ3 := ZS_SEND;
        END_IF
    ZS_SEND:
        IF xA3 THEN
            iZ3 := ZS_EMPTY;
        END_IF
END_CASE

(* ---------- Saídas (calculadas após a lógica de estados) ---------- *)
xMotor1 := xActive AND ((iZ1 = ZS_RECV) OR (iZ1 = ZS_SEND));
xMotor2 := xActive AND ((iZ2 = ZS_RECV) OR (iZ2 = ZS_SEND));
xMotor3 := xActive AND ((iZ3 = ZS_RECV) OR ((iZ3 = ZS_SEND) AND xDownMachineReady));

xUpMachineReady := xActive AND ((iZ1 = ZS_EMPTY) OR (iZ1 = ZS_RECV));
xDownBoardAvail := (iZ3 = ZS_SEND);
xBoardInAsm     := (iZ2 = ZS_OCC);
xBoardInInsp    := (iZ3 = ZS_OCC);

IF xFirst THEN
    uiLast := iHeartbeat;
    xFirst := FALSE;
END_IF

xChanged := (iHeartbeat <> uiLast);
uiLast := iHeartbeat;

tonLoss(IN := NOT xChanged, PT := tTimeout);
xLost := tonLoss.Q;
xOk := NOT tonLoss.Q;

rtCond(CLK := xCondition);
rtAck(CLK := xAck);
rtRst(CLK := xReset);

IF rtCond.Q THEN
    xActive := TRUE;
    xAcked := FALSE;
END_IF

IF rtAck.Q AND xActive THEN
    xAcked := TRUE;
END_IF

(* Reset só é aceito com alarme reconhecido e condição normalizada *)
IF rtRst.Q AND xActive AND xAcked AND NOT xCondition THEN
    xActive := FALSE;
    xAcked := FALSE;
END_IF

rtReq(CLK := xRequest);

IF rtReq.Q THEN
    IF xMachineStopped AND (iRequested >= 1) AND (iRequested <= c_NUM_RECIPES) THEN
        iActive := iRequested;
        xRejected := FALSE;
    ELSE
        xRejected := TRUE;
    END_IF
END_IF
IF NOT xRequest THEN
    xRejected := FALSE;
END_IF

(* Validação da receita ativa *)
xOk := (iActive >= 1) AND (iActive <= c_NUM_RECIPES);
IF xOk THEN
    xOk := (aRecipes[iActive].iCount >= 1) AND (aRecipes[iActive].iCount <= c_MAX_COMP);
END_IF
IF xOk THEN
    FOR i := 1 TO aRecipes[iActive].iCount DO
        stC := aRecipes[iActive].aComp[i];
        IF NOT (F_InRange(stC.rPickX, rXMin, rXMax)
            AND F_InRange(stC.rPickY, rYMin, rYMax)
            AND F_InRange(stC.rPlaceX, rXMin, rXMax)
            AND F_InRange(stC.rPlaceY, rYMin, rYMax)
            AND F_InRange(stC.rPlaceTheta, -180.0, 180.0)) THEN
            xOk := FALSE;
            EXIT;
        END_IF
    END_FOR
END_IF
xValid := xOk;

(* Perda imediata; rearme somente após 500 ms de condição normal *)
tonRearm(IN := xEStopOk AND xDoorClosed, PT := T#500MS);
xSafetyOk := tonRearm.Q;

(* Heartbeat da IHM *)
fbHmi(iHeartbeat := iHmiHeartbeat, tTimeout := tHmiTimeout);
xHmiOk := fbHmi.xOk;

(* Condições de alarme *)
aCond[c_ALM_ESTOP]       := NOT xEStopOk;
aCond[c_ALM_DOOR]        := NOT xDoorClosed;
aCond[c_ALM_HMI]         := NOT xHmiOk;
aCond[c_ALM_CONVEYOR]    := xConveyorFault;
FOR i := 1 TO 4 DO
    aCond[c_ALM_AXIS_X + i - 1] := xAxisFault[i];
END_FOR
aCond[c_ALM_CLAMP]       := xClampFault;
aCond[c_ALM_STOPPER]     := xStopperFault;
aCond[c_ALM_PICK_FAIL]   := xPickFail;
aCond[c_ALM_VAC_LOSS]    := xGripLoss;
aCond[c_ALM_AOI_TIMEOUT] := xAoiTimeout;
aCond[c_ALM_RECIPE]      := xStartRefusedRecipe;
aCond[c_ALM_Z_INTERLOCK] := xZInterlockFault;

(* Processamento e consolidação *)
xAnyAlarm := FALSE;
xAnyUnacked := FALSE;
FOR i := 1 TO c_NUM_ALARMS DO
    fbAlarm[i](xCondition := aCond[i], xAck := xCmdAck, xReset := xCmdReset);
    xAlarmActive[i] := fbAlarm[i].xActive;
    xAlarmAcked[i]  := fbAlarm[i].xAcked;
    IF fbAlarm[i].xActive THEN
        xAnyAlarm := TRUE;
        IF NOT fbAlarm[i].xAcked THEN
            xAnyUnacked := TRUE;
        END_IF
    END_IF
END_FOR

rtReset(CLK := xCmdReset);
rtStart(CLK := xCmdStart);
rtStop(CLK := xCmdStop);
rtHome(CLK := xCmdHome);
xResetPulse := rtReset.Q;
xStartRefusedRecipe := FALSE;

(* Receitas: troca somente com a máquina parada *)
xStopped := (eMachineState <> E_MachineState.RUNNING) AND (eMachineState <> E_MachineState.HOMING);
fbRecipe(xRequest := xCmdRecipeSel,
         iRequested := iRecipeReq,
         xMachineStopped := xStopped,
         rXMin := rAxisMin[c_AX_X], rXMax := rAxisMax[c_AX_X],
         rYMin := rAxisMin[c_AX_Y], rYMax := rAxisMax[c_AX_Y],
         aRecipes := aRecipes);
iRecipeActive   := fbRecipe.iActive;
xRecipeValid    := fbRecipe.xValid;
xRecipeRejected := fbRecipe.xRejected;

(* Emergência e porta sobrepõem qualquer estado *)
IF NOT xSafetyOk THEN
    eMachineState := E_MachineState.ESTOP;
ELSE
    CASE eMachineState OF
        E_MachineState.INIT, E_MachineState.ESTOP:
            IF xAnyAlarm THEN
                eMachineState := E_MachineState.ALARM;
            ELSE
                eMachineState := E_MachineState.STOPPED;
            END_IF

        E_MachineState.STOPPED:
            IF xAnyAlarm THEN
                eMachineState := E_MachineState.ALARM;
            ELSIF rtHome.Q THEN
                eMachineState := E_MachineState.HOMING;
            ELSIF rtStart.Q THEN
                IF NOT xAllHomed THEN
                    ;   (* Partida ignorada: eixos não referenciados *)
                ELSIF NOT xRecipeValid THEN
                    xStartRefusedRecipe := TRUE;
                ELSE
                    eMachineState := E_MachineState.RUNNING;
                END_IF
            END_IF

        E_MachineState.HOMING:
            IF xAnyAlarm THEN
                eMachineState := E_MachineState.ALARM;
            ELSIF xHomeSeqDone THEN
                eMachineState := E_MachineState.STOPPED;
            END_IF

        E_MachineState.RUNNING:
            IF xAnyAlarm THEN
                eMachineState := E_MachineState.ALARM;
            ELSIF rtStop.Q THEN
                eMachineState := E_MachineState.STOPPED;
            END_IF

        E_MachineState.ALARM:
            IF NOT xAnyAlarm THEN
                eMachineState := E_MachineState.STOPPED;
            END_IF
    END_CASE
END_IF

(* Habilitações derivadas do estado *)
xDrivesEnable := xSafetyOk;
xAutoEnable   := (eMachineState = E_MachineState.RUNNING);
xMotionRun    := xAutoEnable OR (eMachineState = E_MachineState.HOMING);
xHomeReq      := (eMachineState = E_MachineState.HOMING);

(* Comandos são pulsos de um ciclo *)
FOR i := 1 TO 4 DO
    xCmdHomeAx[i] := FALSE;
    xCmdMoveAx[i] := FALSE;
END_FOR
xZInterlockFault := FALSE;

xZSafe    := rAxisActPos[c_AX_Z] >= (rZSafe - rZTol);
xAccXYT   := fbAx[c_AX_X].xAccept AND fbAx[c_AX_Y].xAccept AND fbAx[c_AX_T].xAccept;
xInPosXYT := fbAx[c_AX_X].xInPos  AND fbAx[c_AX_Y].xInPos  AND fbAx[c_AX_T].xInPos;
xHomedXYT := fbAx[c_AX_X].xHomed  AND fbAx[c_AX_Y].xHomed  AND fbAx[c_AX_T].xHomed;

IF (NOT xMotionRun) OR xMotionFault THEN
    (* Aborta os serviços *)
    iSvc := SV_IDLE;
    xXYTDone := FALSE;
    xZDone := FALSE;
    xHomeSeqDone := FALSE;
ELSE
    CASE iSvc OF
        SV_IDLE:
            xXYTDone     := xXYTDone AND xMoveXYTReq;
            xZDone       := xZDone AND xMoveZReq;
            xHomeSeqDone := xHomeSeqDone AND xHomeReq;
            IF xHomeReq AND NOT xHomeSeqDone THEN
                iSvc := SV_HOME_Z;
            ELSIF xMoveXYTReq AND NOT xXYTDone AND xAllHomed THEN
                IF xZSafe THEN
                    iSvc := SV_XYT_GO;
                ELSE
                    xZInterlockFault := TRUE;   (* XYθ só com Z na altura segura *)
                END_IF
            ELSIF xMoveZReq AND NOT xZDone AND xAllHomed THEN
                iSvc := SV_Z_GO;
            END_IF

        (* ----- Sequência de homing ----- *)
        SV_HOME_Z:
            IF fbAx[c_AX_Z].xAccept THEN
                xCmdHomeAx[c_AX_Z] := TRUE;
                iSvc := SV_HOME_Z_W;
            END_IF
        SV_HOME_Z_W:
            IF fbAx[c_AX_Z].xHomed AND fbAx[c_AX_Z].xInPos THEN
                iSvc := SV_Z_SAFE;
            END_IF
        SV_Z_SAFE:
            rTgt[c_AX_Z] := rZSafe;
            IF fbAx[c_AX_Z].xAccept THEN
                xCmdMoveAx[c_AX_Z] := TRUE;
                iSvc := SV_Z_SAFE_W;
            END_IF
        SV_Z_SAFE_W:
            IF fbAx[c_AX_Z].xInPos THEN
                iSvc := SV_HOME_XYT;
            END_IF
        SV_HOME_XYT:
            IF xAccXYT THEN
                xCmdHomeAx[c_AX_X] := TRUE;
                xCmdHomeAx[c_AX_Y] := TRUE;
                xCmdHomeAx[c_AX_T] := TRUE;
                iSvc := SV_HOME_XYT_W;
            END_IF
        SV_HOME_XYT_W:
            IF xHomedXYT AND xInPosXYT THEN
                iSvc := SV_PARK;
            END_IF
        SV_PARK:
            rTgt[c_AX_X] := rParkX;
            rTgt[c_AX_Y] := rParkY;
            rTgt[c_AX_T] := rParkT;
            IF xAccXYT THEN
                xCmdMoveAx[c_AX_X] := TRUE;
                xCmdMoveAx[c_AX_Y] := TRUE;
                xCmdMoveAx[c_AX_T] := TRUE;
                iSvc := SV_PARK_W;
            END_IF
        SV_PARK_W:
            IF xInPosXYT THEN
                xHomeSeqDone := TRUE;
                iSvc := SV_IDLE;
            END_IF

        (* ----- Movimento XYθ ----- *)
        SV_XYT_GO:
            rTgt[c_AX_X] := rTgtX;
            rTgt[c_AX_Y] := rTgtY;
            rTgt[c_AX_T] := rTgtT;
            IF xAccXYT THEN
                xCmdMoveAx[c_AX_X] := TRUE;
                xCmdMoveAx[c_AX_Y] := TRUE;
                xCmdMoveAx[c_AX_T] := TRUE;
                iSvc := SV_XYT_W;
            END_IF
        SV_XYT_W:
            IF xInPosXYT THEN
                xXYTDone := TRUE;
                iSvc := SV_IDLE;
            END_IF

        (* ----- Movimento Z ----- *)
        SV_Z_GO:
            rTgt[c_AX_Z] := rTgtZ;
            IF fbAx[c_AX_Z].xAccept THEN
                xCmdMoveAx[c_AX_Z] := TRUE;
                iSvc := SV_Z_W;
            END_IF
        SV_Z_W:
            IF fbAx[c_AX_Z].xInPos THEN
                xZDone := TRUE;
                iSvc := SV_IDLE;
            END_IF
    END_CASE
END_IF

(* Execução dos eixos *)
xAllHomed := TRUE;
xMotionFault := FALSE;
FOR i := 1 TO 4 DO
    fbAx[i](xEnable        := xDrivesEnable,
            xReset         := xResetPulse,
            xHomeCmd       := xCmdHomeAx[i],
            xMoveCmd       := xCmdMoveAx[i],
            xHalt          := (NOT xMotionRun) OR xMotionFault,
            rTarget        := rTgt[i],
            rActPos        := rAxisActPos[i],
            rSoftMin       := rAxisMin[i],
            rSoftMax       := rAxisMax[i],
            xDriveReady    := xAxisDriveReady[i],
            xDriveFault    := xAxisDriveFault[i],
            xDriveHomeDone := xAxisHomeDone[i]);

    xAxisPower[i]    := fbAx[i].xDrivePower;
    xAxisHome[i]     := fbAx[i].xDriveHome;
    xAxisExecute[i]  := fbAx[i].xDriveExecute;
    rAxisSetpoint[i] := fbAx[i].rDriveSetpoint;
    xAxisFault[i]    := fbAx[i].xFault;

    xAllHomed := xAllHomed AND fbAx[i].xHomed;
    IF fbAx[i].xFault THEN
        xMotionFault := TRUE;
    END_IF
END_FOR

fbConv(xEnable           := xAutoEnable AND xSafetyOk,
       xReset            := xResetPulse,
       xClearZones       := xCmdClearZones AND NOT xAutoEnable,
       xSensZ1           := xSensZ1,
       xSensZ2           := xSensZ2,
       xSensZ3           := xSensZ3,
       xUpBoardAvail     := xSmemaUpAvail,
       xDownMachineReady := xSmemaDownReady,
       xAsmDone          := xAsmDone,
       xInspDone         := xInspDone,
       tTransferTimeout  := tConvTimeout);

xMotor1         := fbConv.xMotor1;
xMotor2         := fbConv.xMotor2;
xMotor3         := fbConv.xMotor3;
xSmemaUpReady   := fbConv.xUpMachineReady;
xSmemaDownAvail := fbConv.xDownBoardAvail;
xBoardInAsm     := fbConv.xBoardInAsm;
xBoardInInsp    := fbConv.xBoardInInsp;
xConveyorFault  := fbConv.xFault;

(* Nova placa na zona de montagem: reinicia a lista de componentes *)
rtBoard(CLK := xBoardInAsm);
IF rtBoard.Q THEN
    iComp := 1;
END_IF

(* Componente corrente da receita ativa *)
IF xRecipeValid AND (iRecipeActive >= 1) AND (iRecipeActive <= c_NUM_RECIPES) THEN
    iCount := aRecipes[iRecipeActive].iCount;
    IF (iComp >= 1) AND (iComp <= iCount) THEN
        stCur := aRecipes[iRecipeActive].aComp[iComp];
    END_IF
ELSE
    iCount := 0;
END_IF

IF NOT xAutoEnable THEN
    (* Aborto seguro: cancela requisições, libera vácuo e grampo *)
    xMoveXYTReq := FALSE;
    xMoveZReq   := FALSE;
    xGripCmd    := FALSE;
    xClampCmd   := FALSE;
    iStep       := S_IDLE;
ELSE
    CASE iStep OF
        S_IDLE:
            IF xAsmDone THEN
                IF NOT xBoardInAsm THEN
                    xAsmDone := FALSE;
                END_IF
            ELSIF xBoardInAsm AND (iCount > 0) THEN
                IF iComp > iCount THEN
                    iStep := S_UNCLAMP;     (* Todos colocados antes do aborto *)
                ELSE
                    iStep := S_CLAMP;
                END_IF
            END_IF

        S_CLAMP:
            xClampCmd := TRUE;
            IF fbClamp.xIsExtended THEN
                iStep := S_LIFT;
            END_IF

        S_LIFT:     (* Garante Z seguro antes de qualquer movimento XY *)
            rTgtZ := rZSafe;
            xMoveZReq := TRUE;
            IF xZDone THEN
                xMoveZReq := FALSE;
                iStep := S_PICK_XY;
            END_IF

        S_PICK_XY:
            rTgtX := stCur.rPickX;
            rTgtY := stCur.rPickY;
            rTgtT := 0.0;
            xMoveXYTReq := TRUE;
            IF xXYTDone THEN
                xMoveXYTReq := FALSE;
                iStep := S_PICK_DOWN;
            END_IF

        S_PICK_DOWN:
            rTgtZ := rZPick;
            xMoveZReq := TRUE;
            IF xZDone THEN
                xMoveZReq := FALSE;
                iStep := S_GRIP;
            END_IF

        S_GRIP:     (* Confirma a pega pelo pressostato *)
            xGripCmd := TRUE;
            IF fbVac.xGripOk THEN
                iStep := S_PICK_UP;
            END_IF

        S_PICK_UP:
            rTgtZ := rZSafe;
            xMoveZReq := TRUE;
            IF xZDone THEN
                xMoveZReq := FALSE;
                iStep := S_PLACE_XY;
            END_IF

        S_PLACE_XY:
            rTgtX := stCur.rPlaceX;
            rTgtY := stCur.rPlaceY;
            rTgtT := stCur.rPlaceTheta;
            xMoveXYTReq := TRUE;
            IF xXYTDone THEN
                xMoveXYTReq := FALSE;
                iStep := S_PLACE_DOWN;
            END_IF

        S_PLACE_DOWN:
            rTgtZ := rZPlace;
            xMoveZReq := TRUE;
            IF xZDone THEN
                xMoveZReq := FALSE;
                iStep := S_RELEASE;
            END_IF

        S_RELEASE:
            xGripCmd := FALSE;
            IF fbVac.xReleased THEN
                iStep := S_PLACE_UP;
            END_IF

        S_PLACE_UP:
            rTgtZ := rZSafe;
            xMoveZReq := TRUE;
            IF xZDone THEN
                xMoveZReq := FALSE;
                iStep := S_NEXT;
            END_IF

        S_NEXT:
            iComp := iComp + 1;
            IF iComp > iCount THEN
                iStep := S_UNCLAMP;
            ELSE
                iStep := S_PICK_XY;
            END_IF

        S_UNCLAMP:
            xClampCmd := FALSE;
            IF fbClamp.xIsRetracted THEN
                iStep := S_DONE;
            END_IF

        S_DONE:     (* Libera a placa para a esteira *)
            xAsmDone := TRUE;
            IF NOT xBoardInAsm THEN
                xAsmDone := FALSE;
                iStep := S_IDLE;
            END_IF
    END_CASE
END_IF

(* Atuadores *)
fbClamp(xEnable         := xSafetyOk,
        xReset          := xResetPulse,
        xCmdExtend      := xClampCmd,
        xSensExtended   := xClampExtended,
        xSensRetracted  := xClampRetracted,
        tMoveTimeout    := tCylTimeout);
xClampValve := fbClamp.xValve;
xClampFault := fbClamp.xFault;

fbVac(xEnable     := xSafetyOk,
      xReset      := xResetPulse,
      xGrip       := xGripCmd,
      xPressostat := xVacuumOk,
      tConfirm    := tVacConfirm);
xVacValve  := fbVac.xVacValve;
xBlowValve := fbVac.xBlowValve;
xPickFail  := fbVac.xPickFail;
xGripLoss  := fbVac.xGripLoss;

(* Zerar contadores somente com o ciclo automático parado *)
rtResetCnt(CLK := xCmdResetCounters);
IF rtResetCnt.Q AND NOT xAutoEnable THEN
    diBoardsProduced := 0;
    diBoardsRejected := 0;
END_IF

(* Supervisão de tempo da AOI *)
tonRes(IN := (iStep = A_WAIT_RESULT), PT := tAoiTimeout);
tonRel(IN := (iStep = A_WAIT_RELEASE), PT := tAoiTimeout);
xAoiTimeout := tonRes.Q OR tonRel.Q;

IF NOT xAutoEnable THEN
    xAoiTrigger := FALSE;
    iStep := A_IDLE;
ELSE
    CASE iStep OF
        A_IDLE:
            IF xInspDone THEN
                IF NOT xBoardInInsp THEN
                    xInspDone := FALSE;
                END_IF
            ELSIF xBoardInInsp THEN
                iFails := 0;
                iStep := A_WAIT_STOP;
            END_IF

        A_WAIT_STOP:    (* Placa contra o batente avançado *)
            IF fbStop.xIsExtended THEN
                iStep := A_WAIT_RESULT;
            END_IF

        A_WAIT_RESULT:
            xAoiTrigger := TRUE;
            IF xAoiDone THEN
                xPass := xAoiPass;
                xAoiTrigger := FALSE;
                iStep := A_WAIT_RELEASE;
            END_IF

        A_WAIT_RELEASE: (* Aguarda a AOI baixar o resultado antes de decidir *)
            IF NOT xAoiDone THEN
                IF xPass THEN
                    xReject := FALSE;
                    iStep := A_RETRACT;
                ELSE
                    iFails := iFails + 1;
                    IF iFails > c_AOI_MAX_RETRY THEN
                        xReject := TRUE;
                        iStep := A_RETRACT;
                    ELSE
                        iStep := A_WAIT_RESULT;     (* Nova tentativa *)
                    END_IF
                END_IF
            END_IF

        A_RETRACT:      (* Recua o batente e então libera a placa *)
            IF fbStop.xIsRetracted THEN
                diBoardsProduced := diBoardsProduced + 1;
                IF xReject THEN
                    diBoardsRejected := diBoardsRejected + 1;
                END_IF
                xCurBoardRejected := xReject;
                xInspDone := TRUE;
                iStep := A_DONE;
            END_IF

        A_DONE:
            IF NOT xBoardInInsp THEN
                xInspDone := FALSE;
                iStep := A_IDLE;
            END_IF
    END_CASE
END_IF

(* Marca de rejeição acompanha a placa até sair da zona de saída *)
IF NOT xBoardInInsp AND NOT xSmemaDownAvail THEN
    xCurBoardRejected := FALSE;
END_IF
xBoardRejectedOut := xCurBoardRejected;

(* Batente: avançado, exceto durante a liberação da placa *)
xStopExtend := NOT ((iStep = A_RETRACT) OR xInspDone);
fbStop(xEnable        := xSafetyOk,
       xReset         := xResetPulse,
       xCmdExtend     := xStopExtend,
       xSensExtended  := xStopExtended,
       xSensRetracted := xStopRetracted,
       tMoveTimeout   := tCylTimeout);
xStopValve    := fbStop.xValve;
xStopperFault := fbStop.xFault;
